# Gera docs/projecao_2026_teste.md a partir dos CSVs da rodada de teste e do relatorio (regra 7: numeros so de CSV). Uso: LC_ALL=C.UTF-8 Rscript scripts/teste_2026_md.R [--data=2026-11-05]
source("R/utils_io.R", encoding = "UTF-8")
args <- commandArgs(TRUE); dia <- sub("^--data=", "", grep("^--data=", args, value = TRUE)); if (!length(dia)) dia <- "2026-11-05"
RD <- dados(file.path("outputs", "teste", "rodada", dia)); SD <- dados(file.path("outputs", "teste", "relatorio_2026"))
r <- function(n) ler_csv(file.path(RD, paste0(n, ".csv"))); s <- function(n) ler_csv(file.path(SD, paste0(n, ".csv")))
cres <- r("p2_projecao"); prim <- r("p2_projecao_primario"); gi <- s("gap_implicito_2026"); gh <- s("gap_historico"); pr <- s("p2_p1_realizado"); dc <- s("decomposicao_2026"); m3 <- s("m3_sombra_2026"); er <- s("srw_erro_por_ano_corte"); rs <- s("srw_erro_eleicao_resumo")
f <- function(x, k = 1, sinal = FALSE) { y <- formatC(x, format = "f", digits = k, decimal.mark = ","); if (sinal) ifelse(x > 0, paste0("+", y), y) else y }
tab <- function(d) { d[] <- lapply(d, function(z) ifelse(is.na(z), "-", as.character(z))); c(paste0("| ", paste(names(d), collapse = " | "), " |"), paste0("|", paste(rep("---", ncol(d)), collapse = "|"), "|"), apply(d, 1, function(z) paste0("| ", paste(z, collapse = " | "), " |"))) }
dv <- function(txt) dc$valor_bi[trimws(dc$componente) == txt]; dvp <- function(pat) dc$valor_bi[grepl(pat, dc$componente, fixed = TRUE)][1]
L <- character(); add <- function(...) L <<- c(L, ...)
add("# Rodada de teste 2026 dos estados: projecao, gap implicito e erro do SRW em anos de eleicao", "",
    sprintf("Rodada de TESTE (sem `--oficial`), `--sem-download --rapida` (**DEGRADADA**), data %s. P2 com dados do RREO ate o b4 (jan-ago); P1 com o SGS ate setembro. **IPCA de 2026 = %s%% (premissas oficiais, informado por Pedro em 05/11/2026)**; o PIB nominal de 2026 e as demais premissas continuam sendo os da fixture (13.300 bi), o que so afeta o m3 (secao 4). Numeros de `outputs/teste/` (`scripts/teste_2026_gap.R`, `scripts/teste_2026_md.R`). **O primario implicito do P2 e descritivo: nao entra na planilha nem no texto do informe; o numero oficial continua sendo o P1 (SRW).**", dia, f(100 * gi$ipca_premissa, 2)), "")
# ---- 1
cc <- cres[cres$oficial %in% c(TRUE, "TRUE"), ]; g <- function(cn, se, v) cc[[v]][cc$conceito == cn & cc$serie == se]
t1 <- data.frame(conceito = c("consolidado (com RPPS, sem intra), 27 UFs", "sem RPPS, sem PR e RS, 25 UFs (ponte)"), `despesa real` = c(f(g("consolidado", "desp:total", "cresc_real_pct"), 1, TRUE), f(g("sem_rpps_ex_PR_RS", "desp:total", "cresc_real_pct"), 1, TRUE)),
  `receita real` = c(f(g("consolidado", "rec:total", "cresc_real_pct"), 1, TRUE), f(g("sem_rpps_ex_PR_RS", "rec:total", "cresc_real_pct"), 1, TRUE)), modelos = paste0("desp ", prim$modelo_despesa, "; rec ", prim$modelo_receita),
  `primario por diferenca 2026 (R$ bi)` = f(prim$primario_prev_bi), `primario 2025 (R$ bi)` = f(prim$primario_ano_ant_bi), check.names = FALSE)
add("## 1. Projecao 2026 dos estados (crescimento real, modelo oficial de cada serie na faixa b3-b4)", "", tab(t1), "",
    "Informe anterior: despesa primaria +6,8% e receita +3,6% (`docs/informe_referencia.md`), em **conceito diferente** (serie sem RPPS, sem PR e RS, previsao feita antes desta especificacao); a linha da ponte e a mais proxima, mas tambem nao e igual. O primario por diferenca e a soma da receita total prevista menos a despesa total prevista, nominais.", "")
# ---- 2
add("## 2. Gap implicito em 2026 (P2 projetado menos P1 dos estados) e comparacao com o realizado", "",
    sprintf("**2026 (corte b4 no P2, mes 9 no P1):** P2 projetado %s bi (receita %s %s bi; despesa %s) menos SRW dos estados %s bi = **gap implicito %s bi** (%s%% da receita projetada). Regra do E3.6 adaptada ao horizonte anual (mediana e MAD do gap realizado, em %% da receita, dos tres anos anteriores; limiar = maior entre 4 MAD e 1%% da receita; referencia = %s anos, todos de 2023 em diante): referencia %s%%, MAD %s%%, limiar %s p.p. => **classe %s**.",
            f(gi$p2_proj_bi), gi$modelo_receita, f(gi$rec_proj_bi), gi$modelo_despesa, f(gi$p1_srw_estaduais_m9_bi), f(gi$gap_impl_bi), f(100 * gi$r_impl, 2), gi$n_ref, f(100 * gi$med_ref, 2), f(100 * gi$mad_ref, 2), f(100 * gi$limiar, 2), toupper(gi$classe)), "",
    "A regra do E3.6 e definida por bimestre; a versao anual e adaptacao nossa (a instabilidade, que exige 6 bimestres, nao se aplica). Gap = P2 menos P1; P2 realizado = receita total menos despesa total das 27 UFs (conceito consolidado); P1 = SGS 4643. Gap implicito historico = P2 projetado no b4 pelo modelo adotado da faixa (backtest do E5, amostra A) menos o SRW dos estados no mes 9 do mesmo ano.", "")
hh <- merge(pr[, c("exercicio", "p2_real_bi", "p1_real_bi", "gap_real_bi", "r_real")], gh[, c("exercicio", "p2_proj_bi", "p2_erro_bi", "p1_srw9_bi", "p1_erro_bi", "gap_impl_bi", "r_impl", "classe_implicito", "classe_realizado")], by = "exercicio", all.x = TRUE)
t2 <- data.frame(ano = hh$exercicio, `P2 real` = f(hh$p2_real_bi), `P1 real` = f(hh$p1_real_bi), `gap real` = f(hh$gap_real_bi, 1, TRUE), `gap real %rec` = f(100 * hh$r_real, 2, TRUE), `classe real` = hh$classe_realizado,
  `P2 proj b4` = f(hh$p2_proj_bi), `erro P2` = f(hh$p2_erro_bi, 1, TRUE), `SRW m9` = f(hh$p1_srw9_bi), `erro SRW` = f(hh$p1_erro_bi, 1, TRUE), `gap implicito` = f(hh$gap_impl_bi, 1, TRUE), `classe implicito` = hh$classe_implicito, check.names = FALSE)
t2 <- rbind(t2, data.frame(ano = 2026, `P2 real` = "-", `P1 real` = "-", `gap real` = "-", `gap real %rec` = "-", `classe real` = "-", `P2 proj b4` = f(gi$p2_proj_bi), `erro P2` = "-", `SRW m9` = f(gi$p1_srw_estaduais_m9_bi), `erro SRW` = "-", `gap implicito` = f(gi$gap_impl_bi, 1, TRUE), `classe implicito` = gi$classe, check.names = FALSE))
t2[] <- lapply(t2, function(z) ifelse(is.na(z) | z == "NA", "-", z))
add(tab(t2), "", "R$ bi; erro = previsao menos realizado, superavit positivo. Realizado so de 2020 em diante: a despesa total de 2015-17 nao esta reconstruida (Anexo 7 depois da carga) e 2018-19 tem UF faltando; antes de 2022 nao ha previsao do E5 com as 27 UFs na amostra A. \"sem_referencia\": 2023 e 2024 nao tem 2 anos na mesma serie (fronteira de 2023 do E3.6).", "")
# ---- 3
v <- function(pat) dvp(pat)
add("## 3. Decomposicao da diferenca (mesmo corte: P2 ate o b4, P1 no mes 8)", "",
    tab(data.frame(componente = trimws(dc$componente), `R$ bi` = f(dc$valor_bi, 1, TRUE), detalhe = ifelse(is.na(dc$detalhe), "", dc$detalhe), check.names = FALSE)), "",
    sprintf("Leitura: do total (%s bi), o acumulado ate o corte contribui com %s bi (P2 acima do P1 em jan-ago) e a hipotese sobre o restante do ano com %s bi. O restante se divide em (ii-a) %s bi, a hipotese do modelo (restante projetado menos o restante realizado de t-1, ambos em R$ do P2), e (ii-b) %s bi, que nao e hipotese: e a diferenca entre o restante de t-1 medido pelo RREO e pelo BCB. O P2 com o restante de t-1 em R$ (B0') daria %s bi.",
            f(v("diferenca total"), 1, TRUE), f(v("(i) acumulado"), 1, TRUE), f(v("(ii) restante"), 1, TRUE), f(v("(ii-a)"), 1, TRUE), f(v("(ii-b)"), 1, TRUE), f(v("B0'"))), "",
    sprintf("Dado dos acumulados: de jan-ago de t-1 para jan-ago de t, o primario acumulado cai de %s para %s bi no P2 e de %s para %s bi no P1; as duas fontes mostram piora, mais forte no RREO. Na receita e na despesa, o restante projetado e de %s e %s bi (t-1: %s e %s).",
            f(v("acumulado jan-ago de t-1, P2")), f(v("acumulado jan-ago de t, P2")), f(v("acumulado jan-ago de t-1, P1")), f(v("acumulado jan-ago de t, P1")), f(v("restante projetado, receita")), f(v("restante projetado, despesa")), f(v("restante(t-1) realizado, receita")), f(v("restante(t-1) realizado, despesa"))), "")
# ---- 4
add("## 4. m3 (sombra) para 2026, so informacao (nao publicar)", "", tab(data.frame(esfera = m3$esfera, `m3 (R$ bi)` = f(m3$m3_bi), `SRW (R$ bi)` = f(m3$srw_bi), `m3 - SRW` = f(m3$m3_menos_srw_bi, 1, TRUE), check.names = FALSE)), "",
    sprintf("PIB nominal de 2026 = %s bi (fixture, nao oficial); o m3 e em %% do PIB, entao o valor muda com a premissa oficial.", formatC(m3$pib_2026_bi[1], format = "f", digits = 0, big.mark = ".", decimal.mark = ",")), "")
# ---- 5
add("## 5. Erro do SRW por esfera e corte: anos de eleicao estadual x demais (descritivo)", "",
    "Erro = SRW menos realizado, R$ bi, **superavit positivo** (convencao do contrato): positivo = o SRW superestima o superavit. No sinal do BCB (deficit positivo) os mesmos erros aparecem com o sinal trocado (por exemplo 2014 e 2022 = -12 e -18). Anos de eleicao estadual: 2010, 2014, 2018, 2022 (n = 4); \"demais\" = 2007-2025 sem esses anos (n = 15); \"sem 2020-21\" tira a pandemia (n = 13). ME = erro medio; MAE = erro absoluto medio.", "")
for (e in c("estaduais", "regional", "municipais")) {
  x <- rs[rs$esfera == e, ]; add(sprintf("**%s**", e), "", tab(data.frame(corte = x$corte, `ME eleicao` = f(x$me_eleicao, 1, TRUE), `MAE eleicao` = f(x$mae_eleicao), `ME demais` = f(x$me_demais, 1, TRUE), `MAE demais` = f(x$mae_demais), `ME demais sem 2020-21` = f(x$me_demais_sem_2020_21, 1, TRUE), `MAE demais sem 2020-21` = f(x$mae_demais_sem_2020_21), check.names = FALSE)), "")
}
ee <- er[er$eleicao_estadual & er$corte %in% c(4, 9) & er$esfera == "estaduais", ]
add("**Estaduais, por ano de eleicao** (cortes 4 e 9):", "", tab(data.frame(ano = ee$ano, corte = ee$corte, `SRW` = f(ee$srw_bi), realizado = f(ee$realizado_bi), erro = f(ee$erro_bi, 1, TRUE), check.names = FALSE)), "",
    "Ressalvas: n = 4; em 2022 coincidem eleicao e LC 194 (corte de ICMS); 2010 e 2018 ficam perto de zero. O padrao e de dois anos grandes e dois nulos, nao de um vies estavel.", "")
# ---- 6
h <- gh[order(gh$exercicio), ]
add("## 6. Leitura para a redacao do informe (descritiva)", "",
    sprintf("1. **O -59,9 bi e a diferenca de dois agregados de cerca de R$ 1,5 tri**; o erro do P2 por diferenca no b4 foi de %s bi (2022), %s (2023), %s (2024) e %s (2025). Um erro de 1%% na receita ja move o primario em cerca de R$ %s bi.", paste(f(h$p2_erro_bi[h$exercicio == 2022], 1, TRUE)), f(h$p2_erro_bi[h$exercicio == 2023], 1, TRUE), f(h$p2_erro_bi[h$exercicio == 2024], 1, TRUE), f(h$p2_erro_bi[h$exercicio == 2025], 1, TRUE), f(0.01 * gi$rec_proj_bi, 0)),
    sprintf("2. O gap implicito historico no mesmo corte foi de %s, %s, %s e %s bi em 2022-2025, contra gaps realizados de %s, %s, %s e %s. O implicito de 2026 (%s bi) e atipico pela regra adaptada, mas o implicito tambem oscilou muito nos outros anos (2024: %s bi), por erro de projecao do P2, nao por gap real.",
            f(h$gap_impl_bi[h$exercicio == 2022], 1, TRUE), f(h$gap_impl_bi[h$exercicio == 2023], 1, TRUE), f(h$gap_impl_bi[h$exercicio == 2024], 1, TRUE), f(h$gap_impl_bi[h$exercicio == 2025], 1, TRUE), f(h$gap_real_bi[h$exercicio == 2022], 1, TRUE), f(h$gap_real_bi[h$exercicio == 2023], 1, TRUE), f(h$gap_real_bi[h$exercicio == 2024], 1, TRUE), f(h$gap_real_bi[h$exercicio == 2025], 1, TRUE), f(gi$gap_impl_bi, 1, TRUE), f(h$gap_impl_bi[h$exercicio == 2024], 1, TRUE)),
    sprintf("3. Metade do restante vem de um fato medido, nao de hipotese: em set-dez de 2025 o RREO registrou %s bi em relacao ao BCB (ii-b). No ano de 2025 o gap total e de %s bi porque esse fim de ano compensou um gap de sinal oposto em jan-ago. Mesmo com o restante de t-1 em R$ nos dois lados (SRW no P2 e no P1), o gap seria de %s bi (P2 B0' menos P1 no mes 8): o gap implicito de 2026 nao e so a hipotese da razao.",
            f(v("(ii-b)"), 1, TRUE), f(pr$gap_real_bi[pr$exercicio == 2025], 1, TRUE), f(v("B0'") - dc$valor_bi[trimws(dc$componente) == "P1 SRW estaduais (mes 8)"], 1, TRUE)),
    sprintf("4. A hipotese do modelo (ii-a) e a razao restante/acumulado de t-1: a despesa (B0) repete a razao de 2025 e, como o acumulado da despesa cresce forte, o restante projetado sobe %s%% nominal contra %s%% na receita. Isso nao e testado como erro em anos de eleicao: a especificacao nao tem dummy eleitoral no E5.",
            f(100 * (v("restante projetado, despesa") / v("restante(t-1) realizado, despesa") - 1)), f(100 * (v("restante projetado, receita") / v("restante(t-1) realizado, receita") - 1))),
    sprintf("5. O SRW do P1 nos estados, em ano de eleicao estadual, errou em media %s bi no corte 9 (demais anos: %s), com 2014 e 2022 explicando quase tudo. Se o erro de 2022 (%s bi) se repetisse, o P1 de 2026 iria de %s para cerca de %s bi, ainda longe do P2 (%s).",
            f(rs$me_eleicao[rs$esfera == "estaduais" & rs$corte == 9], 1, TRUE), f(rs$me_demais[rs$esfera == "estaduais" & rs$corte == 9], 1, TRUE), f(er$erro_bi[er$esfera == "estaduais" & er$ano == 2022 & er$corte == 9], 1, TRUE), f(gi$p1_srw_estaduais_m9_bi), f(gi$p1_srw_estaduais_m9_bi - er$erro_bi[er$esfera == "estaduais" & er$ano == 2022 & er$corte == 9]), f(gi$p2_proj_bi)), "",
    "Redacao possivel (decisao de Pedro): manter o P1 como numero e, se o texto mencionar o RREO, falar de receita e despesa (crescimento real) e nao do primario implicito; ou citar a divergencia como risco de baixa sem numero do P2.", "")
writeLines(L, "docs/projecao_2026_teste.md", useBytes = TRUE); cat("docs/projecao_2026_teste.md gerado\n")
